#include "jerico/shelf_props.hpp"
#include "jerico/export.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <set>
using namespace jerico;
int main(int argc,char**argv){try{std::string out="shelf-props-out",recipe,shelf;int resolution=384;for(int i=1;i<argc;i++){std::string a=argv[i];if(a=="--out"&&i+1<argc)out=argv[++i];else if(a=="--bake"&&i+1<argc)resolution=std::stoi(argv[++i]);else if(a=="--recipe"&&i+1<argc)recipe=argv[++i];else if(a=="--shelf-scene"&&i+1<argc)shelf=argv[++i];else throw std::invalid_argument("Usage: jerico_shelf_props --out DIR [--recipe JSON] [--bake 384] [--shelf-scene JSON]");}Json r=Json::object();if(!recipe.empty()){std::ifstream f(recipe);if(!f)throw std::runtime_error("Cannot read recipe");f>>r;}auto s=evaluate_shelf_props(build_shelf_props(r));auto errors=validate_scene(s);if(!errors.empty())throw std::runtime_error(errors.dump());bake_shelf_props(s,out+"/native-textures",resolution);write_glb(s,out+"/shelf-props.glb");write_obj_mtl(s,out+"/shelf-props.obj");std::ofstream(out+"/scene.json")<<s.dump();std::ofstream(out+"/recipe.json")<<s["recipe"].dump(2);
 for(auto item:s["metadata"]["items"]){auto q=s;std::string id=item["id"],name=id.substr(5);V3 origin=item["pivot"];q["parts"]=Json::array();for(auto p:s["parts"])if(p["item_id"]==id){for(auto&v:p["vertices"])v=sub(v.get<V3>(),origin);q["parts"].push_back(p);}item["pivot"]=V3{0,0,0};item["bottom_plane_z"]=0;item["obb"]["center"]=sub(item["obb"]["center"].get<V3>(),origin);item["grab"]["position"]=sub(item["grab"]["position"].get<V3>(),origin);q["metadata"]["items"]=Json::array({item});q["metadata"]["asset_id"]=id;write_glb(q,out+"/"+name+".glb");std::ofstream(out+"/"+name+".scene.json")<<q.dump();}
 if(!shelf.empty()){std::ifstream f(shelf);if(!f)throw std::runtime_error("Cannot read shelf scene");Json sh;f>>sh;auto placements=plan_shelf_prop_placement(sh,s);std::ofstream(out+"/placement.json")<<placements.dump(2);
  Json integrated=sh;for(const auto&placement:placements["placements"])if(placement["status"]=="placed"){std::string id=placement["id"];V3 shift=placement["translation"];for(auto part:s["parts"])if(part["item_id"]==id){for(auto&v:part["vertices"])v=add(v.get<V3>(),shift);integrated["parts"].push_back(part);}for(auto item:s["metadata"]["items"])if(item["id"]==id){item["obb"]=placement["obb"];item["pivot"]=placement["pivot"];item["bottom_plane_z"]=item["bottom_plane_z"].get<double>()+shift[2];item["grab"]["position"]=add(item["grab"]["position"].get<V3>(),shift);item["compartment"]=placement["compartment"];item["support_id"]=placement["support_id"];item["pose_mode"]="upright";integrated["metadata"]["items"].push_back(item);}}
  std::set<std::string> material_ids;int max_resolution=0;for(const auto&part:integrated["parts"]){material_ids.insert(part.value("material_shared_id",part["id"].get<std::string>()));max_resolution=std::max(max_resolution,part["textures"].value("resolution",0));}integrated["metadata"]["native_material_bake"]["family"]="bookshelf_with_shelf_props";integrated["metadata"]["native_material_bake"]["shared_material_count"]=material_ids.size();integrated["metadata"]["native_material_bake"]["maximum_material_families"]=material_ids.size();integrated["metadata"]["native_material_bake"]["maximum_resolution"]=max_resolution;integrated["metadata"]["shelf_props_placement"]=placements;integrated["metadata"]["deferred_accessories"]=Json::array();integrated["metadata"]["item_count"]=integrated["metadata"]["items"].size();write_glb(integrated,out+"/shelf-with-props.glb");std::ofstream(out+"/shelf-with-props.scene.json")<<integrated.dump();}
 size_t tris=0;for(auto&p:s["parts"])for(auto&f:p["faces"])tris+=f.size()-2;Json metrics={{"items",s["metadata"]["items"].size()},{"parts",s["parts"].size()},{"triangles",tris},{"texture_resolution",resolution},{"shared_materials",s["metadata"]["native_material_bake"]["shared_material_count"]},{"native_cpp",true},{"validation",errors}};std::ofstream(out+"/metrics.json")<<metrics.dump(2);std::cout<<metrics.dump(2)<<'\n';
}catch(const std::exception&e){std::cerr<<"ERROR "<<e.what()<<'\n';return 1;}}
